// src/main/utils/request-signature.ts
import { createHash } from 'node:crypto'

const mapBodyToSignatureString = (body: unknown, parentKey = ''): string => {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return ''

  const entries = Object.entries(body as Record<string, unknown>)
    .sort(([a], [b]) => a.localeCompare(b))

  let keys = ''

  for (const [key, value] of entries) {
    const finalKey = parentKey ? `${parentKey}.${key}` : key

    if (Array.isArray(value)) {
      keys += finalKey
      continue
    }

    if (value && typeof value === 'object') {
      keys += mapBodyToSignatureString(value, finalKey)
      continue
    }

    keys += `${finalKey}${String(value ?? '')}`
  }

  return keys
}

export const buildRequestSecurityHeaders = (
  payload: Record<string, unknown>,
  email = '0'
): Record<'timestamp' | 'email' | 'sig', string> => {
  const timestamp = Date.now()
  const signaturePayload = {
    ...payload,
    timestamp,
    email: payload.email ?? email,
  }
  const keys = mapBodyToSignatureString(signaturePayload)
  const sig = createHash('sha1').update(keys).digest('hex')

  return {
    timestamp: String(timestamp),
    email,
    sig,
  }
}

// src/renderer/src/hooks/useLocalStorage.ts
import { useEffect, useState } from "react";
import CryptoJS from "crypto-js";

type SetValue<T> = T | ((val: T) => T);

interface UseLocalStorageOptions {
  encrypted?: boolean;
}

const SECRET_KEY = `${import.meta.env.VITE_SECRET_KEY}`;

export const setData = (storageKey: string, value: any) => {
  try {
    const jsonValue = JSON.stringify(value);
    const encrypted = CryptoJS.AES.encrypt(jsonValue, SECRET_KEY).toString();
    localStorage.setItem(storageKey, encrypted);
    window.dispatchEvent(new Event("storage"));
  } catch (e) {
    console.error("Gagal menyimpan di localStorage", e);
    return null;
  }
};

export const getData = (storageKey: string) => {
  try {
    const encrypted = localStorage.getItem(storageKey);
    if (!encrypted) return null;
    const bytes = CryptoJS.AES.decrypt(encrypted, SECRET_KEY);
    const decrypted = bytes.toString(CryptoJS.enc.Utf8);
    if (!decrypted) {
      localStorage.removeItem(storageKey);
      return null;
    }
    return JSON.parse(decrypted);
  } catch (e) {
    localStorage.removeItem(storageKey);
    return null;
  }
};

function useLocalStorage<T>(
  key: string,
  initialValue: T,
  options: UseLocalStorageOptions = {}
): [T, (value: SetValue<T>) => void] {
  const { encrypted = false } = options;
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = encrypted ? getData(key) : localStorage.getItem(key);
      if (item !== null) return encrypted ? item : JSON.parse(item);
      return initialValue;
    } catch {
      return initialValue;
    }
  });

  useEffect(() => {
    const handleStorageChange = () => {
      try {
        const newValue = encrypted ? getData(key) : localStorage.getItem(key);
        setStoredValue(newValue !== null ? (encrypted ? newValue : JSON.parse(newValue)) : initialValue);
      } catch (error) {
        console.error("Error syncing storage:", error);
      }
    };
    window.addEventListener("storage", handleStorageChange);
    return () => window.removeEventListener("storage", handleStorageChange);
  }, [key, encrypted, initialValue]);

  const setValue = (value: SetValue<T>) => {
    const newValue = value instanceof Function ? value(storedValue) : value;
    setStoredValue(newValue);
    if (encrypted) {
      setData(key, newValue);
    } else {
      localStorage.setItem(key, JSON.stringify(newValue));
      window.dispatchEvent(new Event("storage"));
    }
  };

  return [storedValue, setValue];
}

// src/renderer/src/lib/invoke-ipc-with-auth-handling.ts
import { clearAuthSession } from './clear-auth-session'
import { IpcServiceError } from './ipc-service-error'
import { extractIpcErrorStatusCode, normalizeIpcErrorMessage } from './normalize-ipc-error-message'
import { toast } from 'sonner'

interface InvokeIpcWithAuthHandlingOptions {
  methodName: string
  fallbackMessage: string
  treatUnauthorizedAsSessionExpired?: boolean
}

const SESSION_EXPIRED_MESSAGE = 'Sesi login telah berakhir. Silakan login kembali.'
const SESSION_EXPIRED_TOAST_COOLDOWN_MS = 3000
let lastSessionExpiredToastAt = 0

export const invokeIpcWithAuthHandling = async <T>(
  action: () => Promise<T>,
  options: InvokeIpcWithAuthHandlingOptions
): Promise<T> => {
  try {
    return await action()
  } catch (error) {
    const statusCode = extractIpcErrorStatusCode(error, { methodName: options.methodName })
    const shouldHandle401AsSessionExpired = options.treatUnauthorizedAsSessionExpired ?? true

    if (statusCode === 401 && shouldHandle401AsSessionExpired) {
      clearAuthSession()
      const now = Date.now()
      if (now - lastSessionExpiredToastAt > SESSION_EXPIRED_TOAST_COOLDOWN_MS) {
        lastSessionExpiredToastAt = now
        toast.error(SESSION_EXPIRED_MESSAGE)
      }
      throw new IpcServiceError(SESSION_EXPIRED_MESSAGE, 401)
    }

    throw new IpcServiceError(
      normalizeIpcErrorMessage(error, {
        methodName: options.methodName,
        fallbackMessage: options.fallbackMessage,
      }),
      statusCode ?? undefined
    )
  }
}

// src/main/services/ws.service.ts
import type { WebContents } from 'electron'
import { WebSocket, type RawData } from 'ws'
import { WS_IPC_CHANNELS } from 'src/shared/ws/channels'

let ws: WebSocket | null = null

export const WsService = {
  connect: (sender: WebContents, url: string): void => {
    if (ws) {
      ws.terminate()
      ws = null
    }

    ws = new WebSocket(url)

    ws.on('open', () => sender.send(WS_IPC_CHANNELS.STATUS, 'connected'))
    ws.on('close', () => sender.send(WS_IPC_CHANNELS.STATUS, 'disconnected'))
    ws.on('error', () => sender.send(WS_IPC_CHANNELS.STATUS, 'error'))
    ws.on('message', (data: RawData) => {
      sender.send(WS_IPC_CHANNELS.MESSAGE, data.toString())
    })
  },

  send: (message: string): void => {
    ws?.send(message)
  },

  disconnect: (): void => {
    ws?.terminate()
    ws = null
  }
}

// src/renderer/src/components/ui/map.tsx & MapSection.tsx
import React from 'react'
import { useMap } from 'react-leaflet'
import { Map, MapLayers, MapMarker, MapTileLayer } from '@/components/ui/map'
import type { IDeviceLocation } from '../data'

interface IMapSectionProps {
  locations: IDeviceLocation[]
  selectedPosition: [number, number] | null
}

const FocusMapMarker: React.FC<{ position: [number, number] | null }> = ({ position }) => {
  const map = useMap()

  React.useEffect(() => {
    if (!position) return

    map.flyTo(position, Math.max(map.getZoom(), 12), {
      animate: true,
      duration: 0.8,
    })
  }, [map, position])

  return null
}

export const MapSection: React.FC<IMapSectionProps> = ({ locations, selectedPosition }) => {
  const mappedLocations = locations.filter(
    (device): device is IDeviceLocation & { position: [number, number] } => device.position !== null
  )

  return (
    <div className="w-full rounded-[12px] bg-accent p-0">
      <div className="overflow-hidden rounded-[12px] border border-[#334155] h-full">
        <Map center={[0.7893, 113.9213]} zoom={5} minZoom={4} className="h-full min-h-0 w-full rounded-none">
          <MapLayers defaultTileLayer="Street">
            <FocusMapMarker position={selectedPosition} />
            <MapTileLayer
              name="Street"
              url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png"
              attribution="&copy; OpenStreetMap contributors, &copy; CARTO"
            />
            <MapTileLayer
              name="Dark"
              url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png"
              attribution="&copy; OpenStreetMap contributors, &copy; CARTO"
            />
            {mappedLocations.map((device) => (
              <MapMarker
                key={device.rowKey}
                position={device.position}
                iconAnchor={[44, 12]}
                icon={
                  <span className="inline-flex h-6 min-w-22 items-center justify-center rounded-full bg-primary px-3 text-xs font-semibold text-white shadow-md">
                    {device.id}
                  </span>
                }
              />
            ))}
          </MapLayers>
        </Map>
      </div>
    </div>
  )
}
